contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory tos, uint v) public payable {
        bool reverted;
        bool ret = false;
        if (tos.length == 0) {
            try c.transfer(from, caddress, tos, v) returns (bool r) {
                reverted = false;
                ret = r;
            } catch {
                reverted = true;
            }
        } else {
            // caller may pass a caddress whose transferFrom reverts, so use try/catch
            try c.transfer(from, caddress, tos, v) returns (bool r) {
                reverted = false;
                ret = r;
            } catch {
                reverted = true;
            }
        }
        if (tos.length == 0) {
            assert(reverted);
        } else {
            assert(!reverted && ret);
        }
    }
    receive() external payable {}
}

