contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    fallback(bytes calldata) external payable returns (bytes memory) {
        // mock token: any transferFrom succeeds
        return abi.encode(true);
    }
    receive() external payable {}
    function run(address from, uint v) public payable {
        require(true);
        address[] memory tos = new address[](2);
        tos[0] = address(0xA11CE);
        tos[1] = address(0xB0B);
        // nonempty list: must not revert and return true
        bool ok = c.transfer(from, address(this), tos, v);
        bool revertedEmpty;
        address[] memory empty = new address[](0);
        try c.transfer(from, address(this), empty, v) { revertedEmpty = false; }
        catch { revertedEmpty = true; }
        assert(ok && revertedEmpty);
    }
}
